// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes32 pubkeyX, bytes32 pubkeyY) public {
        vm.assume(caller != address(0)); // to avoid trivial cases
        vm.prank(caller);
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSignature("logRegisteredPubkey(bytes32,bytes32)", pubkeyX, pubkeyY)
        );
        bool returnValue = ok && abi.decode(ret, (bool));
        bool approved = c.approvedToLog(caller);
        assertTrue(returnValue == approved);
    }
}

